import asyncio
import pytest
from app.evaluators.deterministic.finding_codes import FindingCodesCorrectnessEvaluator

class DummyCase:
    def __init__(self, expected_output):
        self.expected_output = expected_output

class DummyExec:
    def __init__(self, output):
        self.output = output

@pytest.mark.asyncio
async def test_evaluator_handles_missing_findings_key():
    case = DummyCase(expected_output={"must_include_finding_codes": []})
    exec_obj = DummyExec(output={})  # 'findings' key absent
    evaluator = FindingCodesCorrectnessEvaluator()
    result = await evaluator.evaluate(case, exec_obj)
    assert result.passed is True
